#include <stdio.h>

struct Node {
  int value;
  struct Node *next;
};

void swapPair(struct Node *node) {
  while (node != NULL && node->next != NULL) {
    int temp = node->value;
    node->value = node->next->value;
    node->next->value = temp;
    node = node->next->next;
  }
}

int main() {
  struct Node n1 = {1, NULL};
  struct Node n2 = {2, NULL};
  struct Node n3 = {3, NULL};
  struct Node n4 = {4, NULL};
  n1.next = &n3;
  n3.next = &n2;
  n2.next = &n4;
  swapPair(&n1);

  struct Node *cur = &n1;
  while (cur != NULL) {
    printf("%d", cur->value);
    cur = cur->next;
  }
  return 0;
}

